<?php
$inviter=new_profile(uid(),'Referral inviter');$old=rec('settings','rewards.referral_paise');put('settings',array_replace($old,['value'=>100]));
try{foreach(['first','second'] as $label){$child=new_profile(uid(),$label);$actor=$child;$result=rpc_route('complete_onboarding',['p_referral_code'=>' '.strtolower($inviter['referral_code']).' ']);ok(rec('profiles',$child['id'])['referred_by']===$inviter['id'],'same referral works for each new member');rpc_route('complete_onboarding',['p_referral_code'=>$inviter['referral_code']]);}ok(count(rows('earnings',$inviter['id']))===2,'one pending reward per distinct invited member');$child=new_profile(uid(),'Self');$actor=$child;denied(fn()=>rpc_route('complete_onboarding',['p_referral_code'=>$child['referral_code']]),422,'self referral rejected');}finally{put('settings',$old);}
